import {canStockSpecies,isCrayfish,releaseBonus} from './catch-model.js';
import {SPECIES,WATERS} from './data.js';
import {fishArt,catchArt} from './art.js';
import {sortCatches,catchSortControl} from './catch-sort.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>new Intl.NumberFormat('nl-NL',{maximumFractionDigits:d}).format(n||0),money=n=>'€ '+num(n,2),kg=n=>num(n,2)+' kg';
const stamp=n=>new Date(n).toLocaleString('nl-NL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const status={1:'Verkocht',2:'Nog af te handelen',3:'In je eigen viswater',4:'Teruggezet',5:'Automatisch verkocht'};
const actions=['sell','release','stock'];
const releaseXp=(game,fish)=>Math.round(releaseBonus(fish)*(1+(game.state.legacy?.wisdom||0)*.05));

export function catchBulkActions(game,rows){
 const available=rows.filter(f=>f.available),fresh=available.some(f=>canStockSpecies(SPECIES.find(s=>s.id===f.species))),owned=game.state.estate.owned;
 return `<div class="journal-bulk" role="group" aria-label="Keuze voor alle openstaande vangsten"><span>Keuze voor alle ${num(available.length)} openstaande vissen:</span><button class="button small" data-journal-bulk="pending" ${!available.length?'disabled':''}>Alles deselecteren</button><button class="button small" data-journal-bulk="sell" ${!available.length?'disabled':''}>Alles verkopen</button><button class="button small" data-journal-bulk="release" ${!available.length?'disabled':''}>Alles terugzetten voor XP</button><button class="button small" data-journal-bulk="stock" ${!owned||!fresh?'disabled':''} title="${owned?'Alle zoetwatervissen overzetten naar je eigen vijver.':'Koop eerst je eigen viswater vanaf level 80.'}">Alles naar eigen vijver</button>${!owned?'<span class="subtle">Eigen viswater vanaf level 80</span>':''}</div>`;
}

export function catchChoice(game,fish){
 if(!fish.available)return `<span class="catch-disposition status-${fish.disposition}">${status[fish.disposition]||'Niet meer aan het water'}</span>`;
 const species=SPECIES.find(item=>item.id===fish.species),canStock=game.state.estate.owned&&canStockSpecies(species),choice=actions.includes(fish.choice)?fish.choice:'';
 return `<select required data-catch-choice="${esc(fish.id)}" aria-label="Keuze voor ${esc(fish.name)} van ${kg(fish.weight)}"><option value="" ${!choice?'selected':''}>Kies wat je doet…</option><option value="sell" ${choice==='sell'?'selected':''}>Verkopen · ${money(fish.value)}</option><option value="release" ${choice==='release'?'selected':''}>Terugzetten · +${num(releaseXp(game,fish))} XP</option><option value="stock" ${choice==='stock'?'selected':''} ${canStock?'':'disabled'}>Naar eigen viswater${isCrayfish(species)?' · niet voor kreeften':!game.state.estate.owned?' · LV 80':''}</option></select>`;
}

export function settlementSummary(game,id='latest'){
 const checkout=Boolean(game.awaitingSettlement),rows=game.sessionRows(checkout?'checkout':id).filter(f=>f.available),sold=rows.filter(f=>f.choice==='sell'),released=rows.filter(f=>f.choice==='release'),stocked=rows.filter(f=>f.choice==='stock'),chosen=sold.length+released.length+stocked.length,pending=rows.length-chosen,cash=sold.reduce((n,f)=>n+f.value,0),xp=released.reduce((n,f)=>n+releaseXp(game,f),0),disabled=!chosen||checkout&&pending>0;
 const label=checkout?(pending?'Kies voor elke vis':'Afhandelen & water verlaten'):'Gekozen vissen verwerken';
 return `<div class="settlement-copy"><span class="eyebrow">${checkout?'VOOR JE VERTREKT':'JOUW KEUZES'}</span><strong>${money(cash)}${xp?` <small>+${num(xp)} XP</small>`:''}</strong><p>${num(sold.length)} verkopen · ${num(released.length)} terugzetten · ${num(stocked.length)} overzetten</p>${pending?`<p class="settlement-pending" data-pending-catches="${pending}">${num(pending)} ${pending===1?'vis wacht':'vissen wachten'} nog op een keuze.</p>`:''}</div><div class="settlement-actions"><p>${checkout?'Handel alle vissen af om dit water te verlaten. Je kunt geen vissen meenemen.':pending?'Vissen zonder keuze blijven aan dit water tot je ze afhandelt.':'Verwerk je geselecteerde vangsten.'}${stocked.length?` ${Math.max(0,game.estateCapacity-game.estatePopulation)} vrije plaatsen in je eigen viswater.`:''}</p><button class="primary" data-action="settle-session" ${disabled?'disabled':''}>${label}${checkout&&pending?' · '+num(pending):''} <span>↗</span></button></div>`;
}

function catchRow(game,fish){
 const species=SPECIES.find(s=>s.id===fish.species);
 return `<tr data-journal-row="${esc(fish.id)}" data-choice="${esc(fish.choice||'')}" data-catch-weight="${esc(fish.weight)}" data-catch-value="${esc(fish.value)}" data-catch-at="${esc(fish.at||0)}"><td><div class="fish-name-cell">${catchArt(species)}<div><strong>${esc(fish.name)} ${fish.trophy?'<span class="gold-text">✧</span>':''}</strong><small>${isCrayfish(species)?'Lastpak · ':''}${fish.best?'Persoonlijk record · ':''}${fish.method==='manual'?fish.rescued?'Beet gered':'Zelf aangeslagen':'Assistent'}${fish.reaction!==null&&fish.reaction!==undefined?' · '+num(fish.reaction,1)+'s':''}</small></div></div></td><td>${kg(fish.weight)}</td><td class="gold-text">${money(fish.value)}</td><td><span>${fish.at?new Date(fish.at).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'Eerdere vangst'}</span><small>+${num(fish.xp)} XP</small></td><td>${catchChoice(game,fish)}</td></tr>`;
}

export function sessionPage(game,{selected='latest',limit=50,sort='time',direction='desc'}={}){
 const awaiting=Boolean(game.awaitingSettlement);
 if(awaiting||selected==='kept')selected='checkout';
 const s=game.state,j=game.journal(selected),rows=game.sessionRows(selected),available=rows.filter(f=>f.available),isLive=Boolean(s.session&&j===s.session),checkout=selected==='checkout',w=WATERS.find(w=>w.id===j?.water),journals=[s.session,...s.sessions].filter(Boolean),value=rows.reduce((n,f)=>n+f.value,0),weight=rows.reduce((n,f)=>n+f.weight,0),visibleLimit=Number.isFinite(limit)?Math.max(1,Math.floor(limit)):50;
 const options=`<option value="latest" ${selected==='latest'?'selected':''}>${s.session?'Lopende sessie':'Laatste sessie'}</option>`+journals.map(j=>`<option value="${j.id}" ${String(selected)===String(j.id)?'selected':''}>${stamp(j.startedAt)} · ${esc(WATERS.find(w=>w.id===j.water)?.name)}${j===s.session?' · LIVE':''}</option>`).join('');
 return `<div class="page-heading"><div><span class="eyebrow"><i class="dot"></i>${awaiting?'JE SESSIE IS AFGELOPEN':'ELKE VANGST TELT'}</span><h1>${awaiting?'Rond je sessie af.':'Sessies & vangsten.'}</h1><p>${awaiting?'Kies voor elke vis: verkopen, terugzetten voor XP of overzetten naar je eigen viswater. Handel alles af voordat je het water verlaat.':'Verkopen is voorgeselecteerd. Verander per vis of voor alles tegelijk de bestemming en verwerk daarna je keuzes.'}</p></div><div class="heading-actions"><button class="button" data-page="home">Naar de waterkant ↗</button></div></div>
 <div class="journal-tabs"><button class="${checkout?'':'active'}" data-journal-tab="latest" ${awaiting?'disabled aria-label="Handel eerst alle vangsten af"':''}>Per sessie</button><button class="${checkout?'active':''}" data-journal-tab="checkout">Openstaande vangsten <b>${num(s.net.length)}</b></button></div>
 ${!checkout?`<div class="journal-toolbar"><label class="field"><span>SESSIE BEKIJKEN</span><select id="journal-select" aria-label="Sessie voor vangstlijst">${options}</select></label><div class="journal-caption"><i class="dot ${isLive?'live-dot':''}"></i><span>${j?isLive?'Deze sessie loopt. Nieuwe vangsten komen erbij.':esc(j.reason||'Sessie afgerond.'):'Start je eerste sessie aan de waterkant.'}<small>Tot 8 recente sessies blijven in je vangstgeschiedenis staan.</small></span></div></div>`:`<div class="notice journal-notice">${awaiting?'Deze vissen moeten allemaal een bestemming krijgen voordat je een nieuwe sessie kunt starten.':'Hier staan alle vissen die nog aan het water wachten op je keuze.'} Terugzetten geeft 20% bonus-XP, met minimaal 3 XP per vis. Een rivierkreeft geeft 1 basis-XP. Je kunt geen vissen meenemen naar een volgende sessie.</div>`}
 <div class="journal-metrics"><div><span>${checkout?'NOG AF TE HANDELEN':'GEVANGEN IN DEZE SESSIE'}</span><b>${num(rows.length)}</b></div><div><span>TOTAAL GEWICHT</span><b>${kg(weight)}</b></div><div><span>BRUTO VANGSTWAARDE</span><b>${money(value)}</b></div><div><span>NOG AAN HET WATER</span><b>${num(available.length)}<small> / ${num(game.capacity)} opslagplaatsen</small></b></div></div>
 <section class="panel journal-panel"><div class="panel-head"><div><span class="eyebrow">${checkout?'GEEF ELKE VIS EEN BESTEMMING':w?esc(w.name.toUpperCase()):'JOUW EERSTE SESSIE'}</span><h2>${checkout?'Wat doe je met je vissen?':j?esc(j.loadout?.name||j.loadoutName):'Hier begint je vangstverhaal'}</h2></div><span class="tag">${isLive?'LIVE VANGSTLIJST':checkout?'OPENSTAAND':j?stamp(j.startedAt):'NOG GEEN SESSIE'}</span></div>
 ${catchSortControl(sort,direction)}${catchBulkActions(game,rows)}
 ${rows.length?`<div class="table-wrap"><table class="data-table journal-table"><thead><tr><th>VANGST</th><th>GEWICHT</th><th>WAARDE</th><th>GEVANGEN</th><th>JOUW KEUZE</th></tr></thead><tbody>${sortCatches(rows,sort,direction).slice(0,visibleLimit).map(f=>catchRow(game,f)).join('')}</tbody></table></div>${rows.length>visibleLimit?`<div class="panel-body"><button class="button" data-action="more-catches">Meer tonen (${num(Math.min(visibleLimit,rows.length))} / ${num(rows.length)})</button></div>`:''}`:`<div class="empty-state">${fishArt('#a8b692')}<h3>${checkout?'Alle vangsten zijn afgehandeld.':'Je volgende vangst komt hier.'}</h3><p>${checkout?'Er liggen geen vissen meer op je keuze te wachten.':'Start een sessie of laat je hengels even hun werk doen.'}</p><button class="primary" data-page="home">Naar de waterkant ↗</button></div>`}
 <div class="journal-footnote">Oudere sessiegeschiedenis wordt bij 40.000 vangsten opgeruimd; je huidige of laatste sessie blijft compleet. ${s.settings.autosell?'Automatische vismarkt staat aan: die vangsten zijn direct verkocht. Zet dit uit bij Instellingen als je per vis wilt kiezen.':'Verkopen, terugzetten of uitzetten gebeurt pas als je hieronder je keuzes verwerkt.'} Verkopen is standaard geselecteerd. Je kunt per vis of met de knoppen bovenaan een andere bestemming kiezen. Tijdens je sessie kun je de keuzes alvast verwerken. Na afloop moet iedere vis een bestemming krijgen. Bij een volle vangstopslag stopt de sessie.</div></section>
 <section class="settlement-bar" id="settlement-summary" aria-label="Vangstkeuzes verwerken">${settlementSummary(game,selected)}</section>`;
}
